#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

/**
 * Problem: 11179 - Wavio Sequence
 * 
 * 解題思路：
 * 1. 對於序列中的每個位置 i，我們需要計算：
 *    - L[i]: 以 i 為結尾的最長遞增子序列 (LIS) 長度。
 *    - R[i]: 以 i 為開頭的最長遞減子序列 (LDS) 長度（等價於從右往左看的 LIS）。
 * 2. 位置 i 能構成的 Wavio 序列最大長度為 2 * min(L[i], R[i]) - 1。
 * 3. 由於 N 可能很大，必須使用 O(N log N) 的 LIS 演算法。
 */

vector<int> getLIS(const vector<int>& v) {
    int n = v.size();
    vector<int> lis(n);
    vector<int> tails;
    for (int i = 0; i < n; ++i) {
        auto it = lower_bound(tails.begin(), tails.end(), v[i]);
        if (it == tails.end()) {
            tails.push_back(v[i]);
            lis[i] = tails.size();
        } else {
            *it = v[i];
            lis[i] = distance(tails.begin(), it) + 1;
        }
    }
    return lis;
}

int main() {
    int n;
    while (cin >> n) {
        vector<int> v(n);
        for (int i = 0; i < n; ++i) cin >> v[i];

        vector<int> L = getLIS(v);

        reverse(v.begin(), v.end());
        vector<int> R = getLIS(v);
        reverse(R.begin(), R.end());

        int max_wavio = 0;
        for (int i = 0; i < n; ++i) {
            max_wavio = max(max_wavio, 2 * min(L[i], R[i]) - 1);
        }
        cout << max_wavio << endl;
    }
    return 0;
}
